#!/usr/bin/env python3
"""verify_r5.py -- self-contained fail-closed verifier: a convex non-ball Schiffer/Pompeiu
domain in R^5 (computer-assisted proof, weighted graded spaces of OW5).

The file embeds the exact dyadic centre, the frozen class parameters and the source of
every stage.  Nothing computed is read from disk: in a NEW EMPTY work directory it
recompiles the native Arb kernels, recomputes every derivative column at the frozen centre,
rebuilds the approximate inverse, recomputes all interval gates, and prints PROVED only if
coverage, Y0, Z0<1, the radii polynomial, strict contraction and the geometry of the whole
existence ball all hold.  Any failure prints NOT_CERTIFIED and exits 2.
Dependencies: numpy, python-flint 0.9.0, gcc, 64-bit Linux (x87 long double).
"""
