def need(ok, message):
    if not ok:
        raise ArithmeticError(message)


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--workdir', help='new or empty work directory')
    ap.add_argument('--output', default='verify_r5_certificate.json')
    ap.add_argument('--jobs', type=int, default=6)
    ap.add_argument('--max-seconds', type=int, default=6 * 3600)
    args = ap.parse_args()
    active = {}
    completed = []
    root = None
    started = time.monotonic()

    def interrupted(signum, frame):
        raise InterruptedError('verifier interrupted')
    signal.signal(signal.SIGTERM, interrupted)
    try:
        need(1 <= args.jobs <= 6, 'jobs must be between 1 and 6')
        for key in ('OMP_NUM_THREADS', 'OPENBLAS_NUM_THREADS', 'MKL_NUM_THREADS'):
            os.environ[key] = '1'
        os.nice(max(0, 19 - os.getpriority(os.PRIO_PROCESS, 0)))
        data = zlib.decompress(base64.b85decode(''.join(PACKED.split())))
        need(hashlib.sha256(data).hexdigest() == PAYLOAD_SHA256, 'embedded payload integrity')
        payload = json.loads(data)
        if args.workdir:
            root = Path(args.workdir).resolve()
            root.mkdir(parents=True, exist_ok=True)
            need(not any(root.iterdir()), 'workdir must be empty')
        else:
            root = Path(tempfile.mkdtemp(prefix='verify_r5_'))
        for name, encoded in payload['files'].items():
            need(Path(name).name == name, 'single-component payload path')
            content = base64.b64decode(encoded)
            need(hashlib.sha256(content).hexdigest() == payload['sha256'][name], 'asset hash ' + name)
            (root / name).write_bytes(content)
        (root / 'logs').mkdir()
        import flint
        need(flint.__version__ == '0.9.0', 'python-flint 0.9.0 required')
        libs = Path(flint.__file__).parent.parent / 'python_flint.libs'
        matches = list(libs.glob('libflint-*.so.*'))
        need(len(matches) == 1, 'unique FLINT shared library')
        gcc = shutil.which('gcc')
        need(gcc is not None, 'gcc required')
        built = subprocess.run([gcc, '-O2', '-fno-fast-math', '-ffp-contract=off', '-fPIC', '-shared', 'n5native.c',
                                str(matches[0]), '-Wl,-rpath,' + str(libs), '-lm', '-o', 'n5native.so'],
                               cwd=root, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=120)
        need(built.returncode == 0, 'native build failed: ' + built.stdout[-2000:])
        P = json.loads((root / 'params.json').read_text())
        print('REPLAY_WORKDIR', root, flush=True)
        tasks = []

        def task(name, deps, *argv, weight=1):
            tasks.append({'name': name, 'deps': set(deps), 'argv': list(argv), 'weight': weight})
        sig = str(P['sigma_factor'])
        task('selftest', [], 'test_native.py')
        task('taylor', ['selftest'], 'stage_taylor.py', 'taylor_fields.json')
        task('resid', ['selftest'], 'stage_resid.py', 'residual', '1024')
        task('shape_tail', ['selftest'], 'stage_cols.py', 'shape', '--jmin', str(L_M + 3), '--jmax', str(P['Nstar'] - 1),
             '--out', 'shape_tail')
        colfiles = []
        for k, rows in enumerate(P['field_row_chunks']):
            task('rows%d' % k, ['selftest'], 'stage_cols.py', 'field', '--rows', rows, '--out', 'rows%d' % k)
            colfiles.append('rows%d' % k)
        task('shape_fin', ['selftest'], 'stage_cols.py', 'shape', '--jmax', str(L_M + 1), '--out', 'shape_fin')
        rowtasks = ['rows%d' % k for k in range(len(P['field_row_chunks']))]
        mjobs = max(1, args.jobs - 2)
        task('matrix', rowtasks + ['shape_fin'], 'stage_matrix.py', '--cols', *colfiles, 'shape_fin',
             '--sigma-factor', sig, '--jobs', str(mjobs), '--out', 'matrix', weight=mjobs)
        task('profiles', ['matrix'], 'stage_profiles.py', '--matrix', 'matrix', '--sigma-factor', sig, '--out', 'profiles.json')
        task('envelopes', ['profiles'], 'stage_env.py', '--profiles', 'profiles.json', '--matrix', 'matrix',
             '--sigma-factor', sig, '--threshold', P['env_threshold'], '--classes', 'params.json', '--out', 'envelopes.json')
        task('far', ['profiles', 'taylor'], 'stage_far.py', '--profiles', 'profiles.json', '--taylor', 'taylor_fields.json',
             '--Nstar', str(P['Nstar']), '--N2', str(P['N2']), '--sigma-factor', sig, '--I', str(P['far_I']), '--out', 'far.json')
        dfiles = []
        for k, f in enumerate(colfiles + ['shape_fin']):
            task('def_%s' % f, ['profiles', f if f != 'shape_fin' else 'shape_fin'], 'stage_defects.py', '--cols', f,
                 '--matrix', 'matrix', '--profiles', 'profiles.json', '--sigma-factor', sig, '--out', 'def_%s.json' % f)
            dfiles.append('def_%s.json' % f)
        task('def_shape_tail', ['profiles', 'shape_tail'], 'stage_defects.py', '--cols', 'shape_tail', '--matrix', 'matrix',
             '--profiles', 'profiles.json', '--sigma-factor', sig, '--out', 'def_shape_tail.json')
        dfiles.append('def_shape_tail.json')
        task('y0', ['profiles', 'resid'], 'stage_defects.py', '--cols', 'residual', '--residual', '--matrix', 'matrix',
             '--profiles', 'profiles.json', '--sigma-factor', sig, '--out', 'y0.json')
        task('assemble', [t['name'] for t in tasks], 'stage_assemble.py', '--matrix', 'matrix', '--profiles', 'profiles.json',
             '--envelopes', 'envelopes.json', '--far', 'far.json', '--residual', 'y0.json', '--defects', *dfiles,
             '--sigma-factor', sig, '--radius', P['radius'], '--out', 'certificate_r5.json')
        pending = list(tasks)
        last = 0
        while pending or active:
            need(time.monotonic() - started < args.max_seconds, 'runtime limit exceeded')
            for t in list(pending):
                used = sum(w for (_, _, _, w) in active.values())
                if used >= args.jobs:
                    break
                if not t['deps'].issubset(completed) or used + t['weight'] > args.jobs:
                    continue
                log = root / 'logs' / (t['name'] + '.log')
                handle = log.open('w')
                proc = subprocess.Popen([sys.executable, '-O', *t['argv']], cwd=root, stdout=handle,
                                        stderr=subprocess.STDOUT, env=os.environ.copy())
                active[t['name']] = (proc, handle, log, t['weight'])
                pending.remove(t)
                print('START', t['name'], 'PID', proc.pid, flush=True)
            for name, (proc, handle, log, _w) in list(active.items()):
                code = proc.poll()
                if code is None:
                    continue
                handle.close()
                del active[name]
                need(code == 0, 'stage ' + name + ' exited ' + str(code) + '; ' + log.read_text(errors='replace')[-2500:])
                completed.append(name)
                print('DONE', name, round(time.monotonic() - started), flush=True)
            need(bool(active) or not pending or any(t['deps'].issubset(completed) for t in pending), 'dependency deadlock')
            if time.monotonic() - last >= 60:
                print('RUNNING', ','.join(active), 'elapsed', round(time.monotonic() - started), flush=True)
                last = time.monotonic()
            if active:
                time.sleep(1)
        for name, wanted in payload['sha256'].items():
            need(hashlib.sha256((root / name).read_bytes()).hexdigest() == wanted, 'source changed during replay: ' + name)
        result = json.loads((root / 'certificate_r5.json').read_text())
        need(result['status'] == 'ALL_EXISTENCE_GATES_PASSED', 'final strict gates')
        result.update({'status': 'PROVED', 'scope': 'Local computer-assisted proof; no external audit asserted.',
                       'replay_workdir': str(root), 'replay_seconds': time.monotonic() - started,
                       'completed_stages': completed,
                       'verifier_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
                       'payload_sha256': PAYLOAD_SHA256})
        Path(args.output).write_text(json.dumps(result, indent=1) + '\n')
        print('PROVED', flush=True)
        print('CERTIFICATE', Path(args.output).resolve(), flush=True)
        return 0
    except BaseException as exc:
        failure = {'status': 'NOT_CERTIFIED', 'reason': str(exc)[-4000:], 'completed_stages': completed,
                   'replay_workdir': str(root)}
        try:
            Path(args.output).write_text(json.dumps(failure, indent=1) + '\n')
        except OSError:
            pass
        print('NOT_CERTIFIED', str(exc)[-3000:], flush=True)
        return 2
    finally:
        for proc, handle, log, _w in active.values():
            if proc.poll() is None:
                proc.terminate()
        for proc, handle, log, _w in active.values():
            try:
                proc.wait(timeout=15)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()
            handle.close()


L_M = 160

if __name__ == '__main__':
    raise SystemExit(main())
